function getCursorPosition(textarea){var rangeData={text:"",start:0,end:0};textarea.focus();if(textarea.setSelectionRange){rangeData.start=textarea.selectionStart;rangeData.end=textarea.selectionEnd;rangeData.text=rangeData.start!=rangeData.end?textarea.value.substring(rangeData.start,rangeData.end):""}else if(document.selection){var i,oS=document.selection.createRange(),oR=document.body.createTextRange();oR.moveToElementText(textarea);rangeData.text=oS.text;rangeData.bookmark=oS.getBookmark();for(i=
0;oR.compareEndPoints("StartToStart",oS)<0&&oS.moveStart("character",-1)!==0;i++)if(textarea.value.charAt(i)=="\n")i++;rangeData.start=i;rangeData.end=rangeData.text.length+rangeData.start}return rangeData}
function setCursorPosition(textarea,rangeData){if(!rangeData);if(textarea.setSelectionRange){textarea.focus();textarea.setSelectionRange(rangeData.start,rangeData.end)}else if(textarea.createTextRange){var oR=textarea.createTextRange();if(textarea.value.length===rangeData.start){oR.collapse(false);oR.select()}else{oR.moveToBookmark(rangeData.bookmark);oR.select()}}}
